def find_xs_files(base_path):
    """Find all .xs files recursively in base_path"""
    xs_files = []
    if not os.path.exists(base_path):
        return xs_files
    for root, dirs, files in os.walk(base_path):
        for f in files:
            if f.endswith('.xs'):
                full_path = os.path.join(root, f)
                xs_files.append(full_path)
    return xs_files

def get_depth(path):
    """Calculate depth of file relative to /app/data/cross_sections"""
    base = "/app/data/cross_sections"
    if path == base:
        return 0
    if path == base + os.sep:
        return 0
    if path.startswith(base + os.sep):
        rel = path[len(base):]
    elif path.startswith(base):
        rel = path[len(base):]
        if rel.startswith(os.sep):
            rel = rel[1:]
    else:
        return 0
    parts = rel.split(os.sep)
    return len(parts) - 1

def sort_files(xs_files):
    """
    Sort files:
    - Deepest directories first (most nested files first)
    - Within same depth, reverse alphabetical by full path (Z to A, case-sensitive)
    """
    def sort_key(path):
        depth = get_depth(path)
        return (depth, path)
    return sorted(xs_files, key=sort_key, reverse=True)

