        parts = line.split(":")
        if len(parts) >= 3:
            iso_name = parts[0]
            density = parts[1]
            mass = parts[2]
            densities[iso_name] = (float(density), float(mass))
    return densities

def match_density(isotope_name, densities_map):
    """Find density info for an isotope"""
    if isotope_name in densities_map:
        return densities_map[isotope_name]
    lower_name = isotope_name.lower()
    for key in densities_map:
        if key.lower() == lower_name:
            return densities_map[key]
    norm_name = normalize_isotope_name(isotope_name)
    for key in densities_map:
        if normalize_isotope_name(key) == norm_name:
            return densities_map[key]
    return None

def find_thermal_cross_section(energies_data):
    """Find thermal cross-section at 0.025 eV"""
    target = 0.025
    best = None  # (distance, eV, sigma_t)
    for data in energies_data:
        eV = data["eV"]
        sigma_t = data["sigma_t"]
        dist = abs(eV - target)
        if dist <= 0.1:
            if best is None or dist < best[0] or (dist == best[0] and eV > best[1]):
                best = (dist, eV, sigma_t)
    if best is None:
        return None
    return best[2]

def check_isotope_name_valid(name):
    """Check if isotope name looks valid"""
    if not name:
        return False
    has_alnum = any(c.isalnum() for c in name)
    return has_alnum

def parse_isotope_info(name):
    """Parse isotope name to extract Z and A"""
    lower_name = name.lower()
    found_z = None
    found_a = None
    for elem, z in ELEMENT_Z.items():
        if elem in lower_name:
            found_z = z
            idx = lower_name.find(elem)
            rest = lower_name[idx+len(elem):]
            match = re.match(r'^-?\d+', rest)
            if match:
                found_a = int(match.group(1))
            break
    if found_z is not None and found_a is not None:
        return (found_z, found_a, name)
    return None

def main():
    base_path = "/app/data/cross_sections"
    density_path = "/app/data/atomic_densities.txt"

    xs_files = find_xs_files(base_path)
    sorted_files = sort_files(xs_files)

    densities = load_atomic_densities(density_path)

    seen_isotopes = {}  # normalized_name -> first source_file (relative path)

    results = []
    total_files = len(sorted_files)
    valid_files = 0
    invalid_files = 0

    for filepath in sorted_files:
        rel_path = os.path.relpath(filepath, "/app/data/cross_sections")
        parsed = parse_file(filepath)

        if parsed["read_error"]:
            invalid_files += 1
        else:
            valid_files += 1

        for iso in parsed["isotopes"]:
            name = iso["name"]
            data = iso["energies"]

            errors = []

            if parsed["read_error"]:
                errors.append("read_error")

            # cross_section_mismatch
            has_mismatch = False
            for dp in data:
                if dp["sigma_t"] is not None and dp["sigma_a"] is not None and dp["sigma_s"] is not None:
                    if abs(dp["sigma_t"] - (dp["sigma_a"] + dp["sigma_s"])) > 0.001:
                        has_mismatch = True
                        break
            if has_mismatch:
                errors.append("cross_section_mismatch")

            # negative_cross_section
            has_negative = False
            for dp in data:
                if dp["sigma_t"] is not None and dp["sigma_t"] < 0:
                    has_negative = True
                if dp["sigma_a"] is not None and dp["sigma_a"] < 0:
                    has_negative = True
                if dp["sigma_s"] is not None and dp["sigma_s"] < 0:
                    has_negative = True
            if has_negative:
                errors.append("negative_cross_section")

            # invalid_energy_ordering
            energy_values = []
            for dp in data:
                if dp["eV"] is not None:
                    energy_values.append(dp["eV"])
            if energy_values:
                if energy_values[0] <= 0:
                    errors.append("invalid_energy_ordering")
                for i in range(1, len(energy_values)):
                    if energy_values[i] <= energy_values[i-1]:
                        errors.append("invalid_energy_ordering")
                        break

            # nan_value / infinity_value
            for dp in data:
                for key in ["eV", "sigma_t", "sigma_a", "sigma_s"]:
                    val = dp.get(key)
                    if val is not None:
                        if math.isnan(val):
                            errors.append("nan_value")
                        elif math.isinf(val):
                            errors.append("infinity_value")

            # duplicate_isotope
            norm_name = normalize_isotope_name(name)
            if norm_name in seen_isotopes:
                errors.append("duplicate_isotope")

            # insufficient_data
            thermal_val = find_thermal_cross_section(data)
            if thermal_val is None:
                errors.append("insufficient_data")

            # missing_density_data
            density_info = match_density(name, densities)
            if density_info is None:
                errors.append("missing_density_data")

            # invalid_isotope_name
            if not check_isotope_name_valid(name):
                errors.append("invalid_isotope_name")

            errors.sort()  # Sort validation_errors alphabetically

            # Determine status based on priority
            priority_order = [
                "corrupted", "invalid_format", "read_error", "cross_section_mismatch",
                "invalid_energy_ordering", "negative_cross_section", "duplicate_isotope",
                "insufficient_data", "missing_density_data", "invalid_isotope_name", "valid"
            ]
            status = "valid"
            if errors:
                for p in priority_order:
                    if p in errors:
                        status = p
                        break

            # Compute output values
            thermal_xs_barns_output = None
            if "insufficient_data" not in errors:
                thermal_val = find_thermal_cross_section(data)
                if thermal_val is not None:
                    thermal_xs_barns_output = round(thermal_val, 6)

            atomic_density_atoms_cm3 = None
            macroscopic_cross_section_cm_minus1 = None
            reaction_rate_reactions_cm3_s = None

            can_compute = not parsed["read_error"] and "missing_density_data" not in errors and "insufficient_data" not in errors
            if can_compute:
                density_info = match_density(name, densities)
                if density_info:
                    density_g = density_info[0]
                    atomic_mass = density_info[1]
                    N_unrounded = (density_g / atomic_mass) * 6.02214076e23
                    thermal_val = find_thermal_cross_section(data)
                    sigma_cm2 = thermal_val * 1e-24
                    macroscopic_unrounded = N_unrounded * sigma_cm2
                    macroscopic_rounded = round(macroscopic_unrounded, 6)
                    atomic_density_atoms_cm3 = round(N_unrounded, 6)
                    macroscopic_cross_section_cm_minus1 = macroscopic_rounded
                    reaction_rate = 1e14 * macroscopic_rounded
                    reaction_rate_reactions_cm3_s = round(reaction_rate, 6)

            result_entry = {
                "isotope": name,
                "source_file": rel_path,
                "status": status,
                "atomic_density_atoms_cm3": atomic_density_atoms_cm3,
                "macroscopic_cross_section_cm_minus1": macroscopic_cross_section_cm_minus1,
                "reaction_rate_reactions_cm3_s": reaction_rate_reactions_cm3_s,
                "thermal_xs_barns": thermal_xs_barns_output,
                "validation_errors": errors
            }
            results.append(result_entry)

            # Track seen isotopes - only first occurrence is valid
            norm_name = normalize_isotope_name(name)
            if norm_name not in seen_isotopes:
                seen_isotopes[norm_name] = rel_path

    # Sort results for output using custom comparator
    def compare_isotopes(a, b):
        info_a = parse_isotope_info(a["isotope"])
        info_b = parse_isotope_info(b["isotope"])
        if info_a is None or info_b is None:
            if a["isotope"] > b["isotope"]:
                return -1
            elif a["isotope"] < b["isotope"]:
                return 1
            return 0

        z_a, a_a, _ = info_a
        z_b, a_b, _ = info_b

        if z_a > z_b:
            return -1
        if z_a < z_b:
            return 1
        if a_a > a_b:
            return -1
        if a_a < a_b:
            return 1
        if a["isotope"] > b["isotope"]:
            return -1
        if a["isotope"] < b["isotope"]:
            return 1
        return 0

    results.sort(key=functools.cmp_to_key(compare_isotopes))

    output = {
        "total_files": total_files,
        "valid_files": valid_files,
        "invalid_files": invalid_files,
        "total_isotopes": len(results),
        "valid_isotopes": sum(1 for r in results if r["status"] == "valid"),
        "invalid_isotopes": sum(1 for r in results if r["status"] != "valid"),
        "isotopes": results
    }

    tmp_path = "/app/cross_section_report.json.tmp"
    with open(tmp_path, 'w') as f:
        json.dump(output, f)
    os.rename(tmp_path, "/app/cross_section_report.json")

if __name__ == "__main__":
    main()
